39: // ─── Helpers de tempo ─────────────────────────────────────────────────────────
40: 
41: function horarioParaMinutos(horario: string): number {
42:   const [h, m] = horario.split(":").map(Number);
43:   return h * 60 + m;
44: }
45: 
46: function hojeLocal(): string {
47:   const d = new Date();
48:   const y = d.getFullYear();
49:   const m = String(d.getMonth() + 1).padStart(2, "0");
50:   const dd = String(d.getDate()).padStart(2, "0");
51:   return `${y}-${m}-${dd}`;
52: }
53: 
54: function minutosAgora(): number {
55:   const d = new Date();
56:   return d.getHours() * 60 + d.getMinutes();
57: }
58: 
59: /**
60:  * Retorna o progresso [0..1] de uma reserva em andamento.
61:  * null se não estiver acontecendo agora.
62:  */
63: function calcularProgressoAtivo(
64:   reserva: Reserva,
65:   dataExibida: string,
66:   agora: number
67: ): number | null {
68:   if (reserva.data !== dataExibida) return null;
69:   const inicio = horarioParaMinutos(reserva.horaInicio);
70:   const fim = horarioParaMinutos(reserva.horaFim);
71:   if (agora < inicio || agora >= fim) return null;
72:   return (agora - inicio) / (fim - inicio);
73: }
74: 
75: /** Formata mm:ss restantes */
76: function formatarTempoRestante(minutosRestantes: number): string {
77:   const m = Math.max(0, Math.floor(minutosRestantes));
78:   const s = Math.max(0, Math.round((minutosRestantes - Math.floor(minutosRestantes)) * 60));
79:   return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
80: }
