118: // ─── Componente: Bloco de Reserva na Timeline ─────────────────────────────────
119: 
120: interface BlocoProps {
121:   reserva: Reserva;
122:   colInicio: number;
123:   duracao: number;
124:   dataExibida: string;
125:   agora: number;
126:   onClick: (reserva: Reserva) => void;
