128: 
129: function BlocoReserva({
130:   reserva,
131:   colInicio,
132:   duracao,
133:   dataExibida,
134:   agora,
135:   onClick,
136: }: BlocoProps) {
137:   const progresso = calcularProgressoAtivo(reserva, dataExibida, agora);
138:   const eAtivo = progresso !== null;
139: 
140:   const fimMin = horarioParaMinutos(reserva.horaFim);
141:   const minutosRestantes = eAtivo ? fimMin - agora : 0;
142: 
143:   const ehBloqueio = reserva.tipoReserva === "manutencao_bloqueio";
144:   const ehManual = reserva.tipoReserva === "admin_manual";
145: 
146:   const style = ehBloqueio
147:     ? {
148:         bg: "bg-amber-500/20",
149:         border: "border-amber-500/50",
150:         text: "text-amber-300",
151:         badge: "bg-amber-500/30 text-amber-300",
152:       }
153:     : ehManual
154:     ? {
155:         bg: "bg-sky-500/20",
156:         border: "border-sky-500/50",
157:         text: "text-sky-300",
158:         badge: "bg-sky-500/30 text-sky-300",
159:       }
160:     : STATUS_STYLE[reserva.status] ?? STATUS_STYLE.pendente;
161: 
162:   const left = COL_LABEL_W + colInicio * SLOT_W + 4;
163:   const width = duracao * SLOT_W - 8;
164: 
165:   return (
166:     <div
167:       onClick={() => onClick(reserva)}
168:       title={`${reserva.nomeCliente} · ${reserva.horaInicio}–${reserva.horaFim}`}
169:       className={`absolute top-2 rounded-xl border cursor-pointer select-none
170:         transition-all duration-150 overflow-hidden group
171:         hover:scale-[1.02] hover:z-20 hover:shadow-lg
172:         ${style.bg} ${style.border}`}
173:       style={{
174:         left,
175:         width,
176:         bottom: 8,
177:       }}
178:     >
179:       {eAtivo && (
180:         <div
181:           className="absolute inset-0 bg-white/5 origin-left transition-none"
182:           style={{ transform: `scaleX(${progresso})` }}
183:         />
184:       )}
185: 
186:       {eAtivo && (
187:         <span className="absolute top-1.5 right-1.5 flex h-2 w-2">
188:           <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
189:           <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-400" />
190:         </span>
191:       )}
192: 
193:       <div className="relative px-2 pt-1.5 pb-1 flex flex-col h-full justify-between">
194:         <div className="flex items-start justify-between gap-1">
195:           <p
196:             className={`text-[10px] font-semibold leading-tight truncate flex-1 ${style.text}`}
197:           >
198:             {(() => {
199:               const telDigits = reserva.whatsappCliente
200:                 ? reserva.whatsappCliente.replace(/\D/g, "")
201:                 : "";
202:               const isMembro = Boolean(
203:                 reserva.userId ||
204:                   (telDigits && getTelefonesCadastradosLocal().has(telDigits))
205:               );
206:               return isMembro ? "⭐ " : "";
207:             })()}
208:             {reserva.tipoReserva === "escolinha"
209:               ? "🎓 "
210:               : reserva.tipoReserva === "grupo"
211:               ? "🔁 "
212:               : reserva.tipoReserva === "admin_manual"
213:               ? "🛡️ "
214:               : ehBloqueio
215:               ? "⚠️ "
216:               : reserva.reservaGratuitaFidelidade || (reserva.descontoFidelidade && reserva.descontoFidelidade > 0)
217:               ? "🎁 "
218:               : ""}
219:             {reserva.nomeCliente || "—"}
220:           </p>
221:           {eAtivo && (
222:             <span className="flex items-center gap-0.5 text-[9px] font-mono text-emerald-400 flex-shrink-0">
223:               <Timer className="w-2.5 h-2.5" />
224:               {formatarTempoRestante(minutosRestantes)}
225:             </span>
226:           )}
227:         </div>
228: 
229:         {width > 64 && (
230:           <div className="flex items-center justify-between gap-1 mt-auto">
231:             {ehBloqueio ? (
232:               <span className="text-[9px] px-1.5 py-0.5 rounded-full leading-none bg-amber-500/30 text-amber-300">
233:                 Bloqueio
234:               </span>
235:             ) : reserva.reservaGratuitaFidelidade ? (
236:               <span className="text-[9px] px-1.5 py-0.5 rounded-full leading-none bg-purple-500/30 text-purple-300 font-bold">
237:                 100% Fidelidade
238:               </span>
239:             ) : reserva.descontoFidelidade && reserva.descontoFidelidade > 0 ? (
240:               <span className="text-[9px] px-1.5 py-0.5 rounded-full leading-none bg-purple-500/30 text-purple-300 font-bold">
241:                 Voucher
242:               </span>
243:             ) : reserva.esporte ? (
244:               <span
245:                 className={`text-[9px] px-1.5 py-0.5 rounded-full leading-none ${style.badge}`}
246:               >
247:                 {reserva.esporte}
248:               </span>
249:             ) : null}
250:             <span
251:               className={`text-[9px] font-mono ${style.text} opacity-70 ml-auto`}
252:             >
253:               {reserva.horaInicio}–{reserva.horaFim}
254:             </span>
255:           </div>
256:         )}
257:       </div>
258:     </div>
259:   );
260: }
