309: // ─── Componente: Linha de Hora Atual na Timeline ─────────────────────────────
310: 
311: function LinhaHoraAtual({
312:   dataExibida,
313:   agora,
314: }: {
315:   dataExibida: string;
316:   agora: number;
317: }) {
318:   if (dataExibida !== hojeLocal()) return null;
319: 
320:   const primeiroSlotMin = horarioParaMinutos(HORARIOS_DISPONIVEIS[0]);
321:   const ultimoSlotMin =
322:     horarioParaMinutos(HORARIOS_DISPONIVEIS[HORARIOS_DISPONIVEIS.length - 1]) +
323:     60;
324: 
325:   if (agora < primeiroSlotMin || agora > ultimoSlotMin) return null;
326: 
327:   const proporcao =
328:     (agora - primeiroSlotMin) / (ultimoSlotMin - primeiroSlotMin);
329:   const totalW = HORARIOS_DISPONIVEIS.length * SLOT_W;
330:   const left = COL_LABEL_W + proporcao * totalW;
331: 
332:   return (
333:     <div
334:       className="absolute top-0 bottom-0 w-px bg-red-500 z-25 pointer-events-none"
335:       style={{ left }}
336:     >
337:       <div className="absolute -top-1 -translate-x-1/2 w-2 h-2 rounded-full bg-red-500" />
338:     </div>
339:   );
340: }
