342: // ─── Componente Principal da Página de Agenda ─────────────────────────────────
343: 
344: type ModoVisualizacao = "calendario" | "grade_dia" | "timeline";
345: 
346: export function AdminAgendaPage() {
347:   const { reservas, carregarReservasDoMes } = useReservasService();
348: 
349:   const hoje = useMemo(() => new Date(), []);
350:   const [modo, setModo] = useState<ModoVisualizacao>("calendario");
351: 
352:   // Estado do Calendário Mensal
353:   const [anoCalendario, setAnoCalendario] = useState(hoje.getFullYear());
354:   const [mesCalendario, setMesCalendario] = useState(hoje.getMonth() + 1);
355: 
356:   // Estado do Dia Selecionado
357:   const [dataSelecionada, setDataSelecionada] = useState(hojeLocal());
358: 
359:   // Estado do Cronômetro da Timeline
360:   const [agora, setAgora] = useState(minutosAgora());
361: 
362:   // Estados de Modais
363:   const [modalReservaAberto, setModalReservaAberto] = useState(false);
364:   const [modalBloqueioAberto, setModalBloqueioAberto] = useState(false);
365:   const [quadraModal, setQuadraModal] = useState<string | undefined>(undefined);
366:   const [horariosModal, setHorariosModal] = useState<string[] | undefined>(undefined);
367:   const [reservaDetalhes, setReservaDetalhes] = useState<Reserva | null>(null);
368: 
369:   // Lazy Loading: Busca dados do mês selecionado sob demanda
370:   useEffect(() => {
371:     void carregarReservasDoMes(anoCalendario, mesCalendario);
372:   }, [anoCalendario, mesCalendario, carregarReservasDoMes]);
373: 
374:   // Tick a cada 10s para atualizar cronômetros da timeline
375:   useEffect(() => {
376:     const interval = setInterval(() => setAgora(minutosAgora()), 10_000);
377:     return () => clearInterval(interval);
378:   }, []);
379: 
380:   // Quando clica num dia no calendário mensal, navega para a grade simplificada daquele dia
381:   function handleSelecionarDiaNoCalendario(dia: string) {
382:     setDataSelecionada(dia);
383:     setModo("grade_dia");
384:   }
385: 
386:   function handleIrParaHoje() {
387:     const agora = new Date();
388:     setAnoCalendario(agora.getFullYear());
389:     setMesCalendario(agora.getMonth() + 1);
390:     setDataSelecionada(hojeLocal());
391:   }
392: 
393:   function abrirReservaManual(quadraId?: string, horario?: string) {
394:     setQuadraModal(quadraId);
395:     setHorariosModal(horario ? [horario] : undefined);
396:     setModalReservaAberto(true);
397:   }
398: 
399:   function abrirBloqueio(quadraId?: string, horario?: string) {
400:     setQuadraModal(quadraId);
401:     setHorariosModal(horario ? [horario] : undefined);
402:     setModalBloqueioAberto(true);
403:   }
404: 
405:   // Reservas do dia exibido na timeline
406:   const reservasDoDia = reservas.filter(
407:     (r) => r.data === dataSelecionada && r.status !== "cancelada"
408:   );
409: 
410:   function dadosPorQuadraTimeline(quadraId: string) {
411:     const reservasQuadra = reservasDoDia
412:       .filter((r) => r.quadraId === quadraId)
413:       .sort((a, b) => a.horaInicio.localeCompare(b.horaInicio));
414: 
415:     const blocos = reservasQuadra.map((r) => {
416:       const colInicio = HORARIOS_DISPONIVEIS.indexOf(r.horaInicio);
417:       const colFim = HORARIOS_DISPONIVEIS.indexOf(r.horaFim);
418:       const duracao =
419:         colFim >= 0
420:           ? colFim - colInicio
421:           : HORARIOS_DISPONIVEIS.length - colInicio;
422:       return { reserva: r, colInicio, duracao };
423:     });
424: 
425:     const alertas: Array<{
426:       colIndex: number;
427:       esporteAnterior: string;
428:       esportePosterior: string;
429:       preparacao: string;
430:     }> = [];
431: 
432:     for (let i = 0; i < reservasQuadra.length - 1; i++) {
433:       const atual = reservasQuadra[i];
434:       const prox = reservasQuadra[i + 1];
435:       const esporteAtual = atual.esporte;
436:       const esporteProx = prox.esporte;
437: 
438:       if (
439:         atual.horaFim === prox.horaInicio &&
440:         esporteAtual &&
441:         esporteProx &&
442:         esporteAtual !== esporteProx
443:       ) {
444:         const colTransicao = HORARIOS_DISPONIVEIS.indexOf(prox.horaInicio);
445:         if (colTransicao >= 0) {
446:           alertas.push({
447:             colIndex: colTransicao,
448:             esporteAnterior: esporteAtual,
449:             esportePosterior: esporteProx,
450:             preparacao:
451:               PREPARACAO_POR_ESPORTE[esporteProx] ?? "Preparação necessária",
452:           });
453:         }
454:       }
455:     }
456: 
457:     return { blocos, alertas };
458:   }
459: 
460:   const isHoje = dataSelecionada === hojeLocal();
461:   const totalW = COL_LABEL_W + HORARIOS_DISPONIVEIS.length * SLOT_W;
462: 
463:   return (
464:     <div className="space-y-6 animate-fade-in">
465:       {/* ── Topbar Principal da Agenda ────────────────────────────────────────── */}
466:       <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
467:         <div>
468:           <h1 className="text-2xl font-bold text-white flex items-center gap-2.5">
469:             <span>Agenda Completa do Admin</span>
470:           </h1>
471:           <p className="text-slate-400 text-sm mt-1">
472:             Controle de reservas online, agendamento manual no balcão e bloqueios de manutenção
473:           </p>
474:         </div>
475: 
476:         {/* Botões de Ação Global */}
477:         <div className="flex flex-wrap items-center gap-2.5">
478:           <button
479:             type="button"
480:             id="admin-agenda-btn-bloquear"
481:             onClick={() => abrirBloqueio()}
482:             className="flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/30 text-amber-300 text-xs font-semibold active:scale-95 transition-all cursor-pointer"
483:           >
484:             <Lock className="w-3.5 h-3.5 text-amber-400" />
485:             Bloquear Horário
486:           </button>
487: 
488:           <button
489:             type="button"
490:             id="admin-agenda-btn-reserva-manual"
491:             onClick={() => abrirReservaManual()}
492:             className="flex items-center gap-1.5 px-4 py-2 rounded-xl bg-sky-500 hover:bg-sky-400 text-slate-950 text-xs font-bold shadow-md shadow-sky-500/20 active:scale-95 transition-all cursor-pointer"
493:           >
494:             <PlusCircle className="w-3.5 h-3.5" />
495:             Nova Reserva Manual
496:           </button>
497:         </div>
498:       </div>
499: 
500:       {/* ── Seletor de Modo de Visualização (Abas) ─────────────────────────────── */}
501:       <div className="flex items-center justify-between border-b border-slate-800 pb-3 flex-wrap gap-3">
