313: /**
314:  * Gera a matriz de dias para a exibição de um mês tradicional de calendário (Domingo a Sábado),
315:  * incluindo os dias de preenchimento dos meses adjacentes e agregando as reservas de cada dia.
316:  *
317:  * @param ano Ano com 4 dígitos (ex.: 2026)
318:  * @param mes Mês de 1 a 12 (ex.: 10 para Outubro)
319:  * @param reservas Lista de reservas para agregação diária
320:  * @param hojeStr Data atual no formato "YYYY-MM-DD"
321:  * @returns Lista completa de dias do grid (normalmente 35 ou 42 células)
322:  */
323: export function gerarDiasCalendarioMensal(
324:   ano: number,
325:   mes: number,
326:   reservas: Reserva[],
327:   hojeStr: string
328: ): DiaCalendarioMensal[] {
329:   // Primeiro dia do mês (0 = domingo ... 6 = sábado)
330:   const primeiroDiaDoMes = new Date(ano, mes - 1, 1);
331:   const diaSemanaInicio = primeiroDiaDoMes.getDay();
332: 
333:   // Quantidade de dias no mês atual
334:   const totalDiasMes = new Date(ano, mes, 0).getDate();
335: 
336:   // Quantidade de dias no mês anterior
337:   const totalDiasMesAnterior = new Date(ano, mes - 1, 0).getDate();
338: 
339:   const grid: DiaCalendarioMensal[] = [];
340: 
341:   // Mapeia reservas por data para busca instantânea O(1)
342:   const mapaReservasPorData = new Map<string, Reserva[]>();
343:   for (const r of reservas) {
344:     if (r.status === "cancelada") continue;
345:     const lista = mapaReservasPorData.get(r.data) || [];
346:     lista.push(r);
347:     mapaReservasPorData.set(r.data, lista);
348:   }
349: 
350:   function criarDia(dataIso: string, diaNumero: number, diaSemana: number, mesAtual: boolean): DiaCalendarioMensal {
351:     const doDia = mapaReservasPorData.get(dataIso) || [];
352:     let totalBloqueios = 0;
353:     let totalReservas = 0;
354:     let totalHorariosOcupados = 0;
355: 
356:     for (const r of doDia) {
357:       if (r.tipoReserva === "manutencao_bloqueio") {
358:         totalBloqueios++;
359:       } else {
360:         totalReservas++;
361:       }
362:       totalHorariosOcupados += r.horarios.length;
363:     }
364: 
365:     return {
366:       data: dataIso,
367:       diaNumero,
368:       diaSemana,
369:       mesAtual,
370:       isHoje: dataIso === hojeStr,
371:       totalReservas,
372:       totalBloqueios,
373:       totalHorariosOcupados,
374:     };
375:   }
376: 
377:   // 1. Preenchimento dos dias finais do mês anterior
378:   const anoAnt = mes === 1 ? ano - 1 : ano;
379:   const mesAnt = mes === 1 ? 12 : mes - 1;
380:   for (let i = diaSemanaInicio - 1; i >= 0; i--) {
381:     const diaNum = totalDiasMesAnterior - i;
382:     const dataIso = `${anoAnt}-${String(mesAnt).padStart(2, "0")}-${String(diaNum).padStart(2, "0")}`;
383:     const diaSemana = (diaSemanaInicio - 1 - i) % 7;
384:     grid.push(criarDia(dataIso, diaNum, diaSemana, false));
385:   }
386: 
387:   // 2. Dias do mês atual
388:   for (let dia = 1; dia <= totalDiasMes; dia++) {
389:     const dataIso = `${ano}-${String(mes).padStart(2, "0")}-${String(dia).padStart(2, "0")}`;
390:     const diaSemana = (diaSemanaInicio + dia - 1) % 7;
391:     grid.push(criarDia(dataIso, dia, diaSemana, true));
392:   }
393: 
394:   // 3. Preenchimento dos dias iniciais do próximo mês para completar a última semana
395:   const restoSemana = grid.length % 7;
396:   if (restoSemana !== 0) {
397:     const diasParaCompletar = 7 - restoSemana;
398:     const anoProx = mes === 12 ? ano + 1 : ano;
399:     const mesProx = mes === 12 ? 1 : mes + 1;
400: 
401:     for (let dia = 1; dia <= diasParaCompletar; dia++) {
402:       const dataIso = `${anoProx}-${String(mesProx).padStart(2, "0")}-${String(dia).padStart(2, "0")}`;
403:       const diaSemana = (grid.length) % 7;
404:       grid.push(criarDia(dataIso, dia, diaSemana, false));
405:     }
406:   }
407: 
408:   return grid;
409: }
