1: /**
2:  * Hook de autenticação mockada para o painel administrativo.
3:  * Usa LocalStorage como mecanismo de sessão front-end.
4:  *
5:  * BACKLOG: Substituir por autenticação real (JWT/OAuth) quando
6:  * houver backend. Ver BACKLOG.md.
7:  */
8: 
9: "use client";
10: 
11: import { useState, useEffect, useCallback } from "react";
12: 
13: const STORAGE_KEY = "reservei_admin_auth";
14: const SENHA_ADMIN = "admin123";
15: 
16: export function useAdminAuth() {
17:   const [autenticado, setAutenticado] = useState<boolean | null>(null); // null = carregando
18: 
19:   // Lê o estado do LocalStorage na montagem (client-only)
20:   useEffect(() => {
21:     try {
22:       const flag = localStorage.getItem(STORAGE_KEY);
23:       setAutenticado(flag === "true");
24:     } catch {
25:       setAutenticado(false);
26:     }
27:   }, []);
28: 
29:   const login = useCallback((senha: string): boolean => {
30:     if (senha === SENHA_ADMIN) {
31:       localStorage.setItem(STORAGE_KEY, "true");
32:       setAutenticado(true);
33:       return true;
34:     }
35:     return false;
36:   }, []);
37: 
38:   const logout = useCallback(() => {
39:     localStorage.removeItem(STORAGE_KEY);
40:     setAutenticado(false);
41:   }, []);
42: 
43:   return { autenticado, login, logout };
44: }
