import { useMemo } from "react";
import {
  CalendarCheck,
  TrendingUp,
  Clock,
  Activity,
  ArrowUpRight,
  GraduationCap,
  UsersRound,
  Wrench,
  ShieldCheck,
  Sparkles,
} from "lucide-react";
import { useReservasService } from "@/hooks/useReservasService";
import { getTelefonesCadastradosLocal } from "@/lib/supabase/authService";
import type { Reserva } from "@/store/useReservasStore";

function formatarMoeda(valor: number) {
  return valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function hoje() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${dd}`;
}

const STATUS_CONFIG: Record<
  string,
  { label: string; cor: string; bg: string }
> = {
  confirmada: {
    label: "Confirmada",
    cor: "text-emerald-400",
    bg: "bg-emerald-500/10 border-emerald-500/20",
  },
  pendente: {
    label: "Pendente",
    cor: "text-amber-400",
    bg: "bg-amber-500/10 border-amber-500/20",
  },
  em_processamento: {
    label: "Processando",
    cor: "text-sky-400",
    bg: "bg-sky-500/10 border-sky-500/20",
  },
  cancelada: {
    label: "Cancelada",
    cor: "text-slate-500",
    bg: "bg-slate-500/10 border-slate-500/20",
  },
};

export function AdminDashboardPage() {
  const { reservas } = useReservasService();
  const dataHoje = hoje();

  const {
    kpis,
    reservasHoje,
    reservasAvulsas,
    reservasEscolinhas,
    reservasGrupos,
    reservasBloqueios,
  } = useMemo(() => {
    const hojeList = reservas
      .filter((r) => r.data === dataHoje && r.status !== "cancelada")
      .sort((a, b) => a.horaInicio.localeCompare(b.horaInicio));

    const sinaisPagos = hojeList.filter(
      (r) => r.status === "confirmada" || r.status === "pendente"
    );

    const totalSinaisRecebidos = sinaisPagos.reduce(
      (acc, r) => acc + r.valorSinal,
      0
    );

    const totalPendenteNoLocal = hojeList
      .filter((r) => r.status === "pendente")
      .reduce((acc, r) => acc + r.valorPendente, 0);

    const totalReservas = hojeList.length;

    // Taxa de ocupação das 3 quadras × 14 horários disponíveis
    const totalSlots = 3 * 14;
    const slotsOcupados = hojeList.reduce(
      (acc, r) => acc + r.horarios.length,
      0
    );
    const taxaOcupacao =
      totalSlots > 0 ? Math.round((slotsOcupados / totalSlots) * 100) : 0;

    const escolinhas = hojeList.filter((r) => r.tipoReserva === "escolinha");
    const grupos = hojeList.filter((r) => r.tipoReserva === "grupo");
    const bloqueios = hojeList.filter((r) => r.tipoReserva === "manutencao_bloqueio");
    const avulsas = hojeList.filter(
      (r) =>
        r.tipoReserva !== "escolinha" &&
        r.tipoReserva !== "grupo" &&
        r.tipoReserva !== "manutencao_bloqueio"
    );

    return {
      kpis: {
        totalReservas,
        totalSinaisRecebidos,
        totalPendenteNoLocal,
        taxaOcupacao,
      },
      reservasHoje: hojeList,
      reservasAvulsas: avulsas,
      reservasEscolinhas: escolinhas,
      reservasGrupos: grupos,
      reservasBloqueios: bloqueios,
    };
  }, [reservas, dataHoje]);

  const cards = [
    {
      id: "kpi-reservas",
      label: "Reservas hoje",
      valor: String(kpis.totalReservas),
      subLabel: "agendamentos ativos",
      icon: CalendarCheck,
      cor: "emerald",
      gradiente: "from-emerald-500/10 to-emerald-500/5",
      borderCor: "border-emerald-500/20",
      iconBg: "bg-emerald-500/10",
      iconCor: "text-emerald-400",
    },
    {
      id: "kpi-sinais",
      label: "Sinais confirmados",
      valor: formatarMoeda(kpis.totalSinaisRecebidos),
      subLabel: "pagos via Pix",
      icon: TrendingUp,
      cor: "sky",
      gradiente: "from-sky-500/10 to-sky-500/5",
      borderCor: "border-sky-500/20",
      iconBg: "bg-sky-500/10",
      iconCor: "text-sky-400",
    },
    {
      id: "kpi-pendente",
      label: "Pendente no local",
      valor: formatarMoeda(kpis.totalPendenteNoLocal),
      subLabel: "a receber presencialmente",
      icon: Clock,
      cor: "amber",
      gradiente: "from-amber-500/10 to-amber-500/5",
      borderCor: "border-amber-500/20",
      iconBg: "bg-amber-500/10",
      iconCor: "text-amber-400",
    },
    {
      id: "kpi-ocupacao",
      label: "Taxa de ocupação",
      valor: `${kpis.taxaOcupacao}%`,
      subLabel: "dos slots disponíveis",
      icon: Activity,
      cor: "violet",
      gradiente: "from-violet-500/10 to-violet-500/5",
      borderCor: "border-violet-500/20",
      iconBg: "bg-violet-500/10",
      iconCor: "text-violet-400",
    },
  ];

  const dataFormatada = new Date().toLocaleDateString("pt-BR", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-white">Visão Geral</h1>
        <p className="text-slate-400 text-sm mt-1 capitalize">{dataFormatada}</p>
      </div>

      {/* KPI Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        {cards.map((card) => {
          const Icon = card.icon;
          return (
            <div
              key={card.id}
              className={`relative bg-gradient-to-br ${card.gradiente} bg-slate-900 border ${card.borderCor} rounded-2xl p-5 overflow-hidden transition-all duration-200 hover:border-slate-600 hover:scale-[1.01] group`}
            >
              <div
                className={`absolute -right-4 -top-4 w-24 h-24 rounded-full ${card.iconBg} blur-2xl opacity-60`}
              />

              <div className="relative">
                <div className="flex items-start justify-between mb-4">
                  <div
                    className={`w-10 h-10 rounded-xl ${card.iconBg} border ${card.borderCor} flex items-center justify-center`}
                  >
                    <Icon className={`w-5 h-5 ${card.iconCor}`} />
                  </div>
                  <ArrowUpRight
                    className={`w-4 h-4 ${card.iconCor} opacity-0 group-hover:opacity-100 transition-opacity duration-200`}
                  />
                </div>

                <p className="text-slate-400 text-xs font-medium mb-1">
                  {card.label}
                </p>
                <p className="text-2xl font-bold text-white leading-none mb-1">
                  {card.valor}
                </p>
                <p className="text-slate-500 text-xs">{card.subLabel}</p>
              </div>
            </div>
          );
        })}
      </div>

      {/* ── Seções Verticais Separadas: Avulsas, Escolinhas e Grupos ──────── */}
      <div className="space-y-7">
        <div className="border-b border-slate-800 pb-3 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
          <div>
            <h2 className="text-base font-bold text-white">
              Operação de Hoje
            </h2>
            <p className="text-xs text-slate-400 mt-0.5">
              Visualização segmentada por modelo de contratação
            </p>
          </div>
          <span className="text-xs font-semibold text-slate-400 bg-slate-900 border border-slate-800 px-3 py-1 rounded-full font-mono self-start sm:self-auto">
            {reservasHoje.length} total de agendamentos
          </span>
        </div>

        {/* 1. Reservas Avulsas & Balcão */}
        <TabelaSecaoReservas
          idSecao="secao-reservas-avulsas"
          titulo="Reservas Avulsas & Balcão"
          subtitulo="Clientes online e agendamentos presenciais"
          icone={CalendarCheck}
          badgeCor="text-emerald-400 bg-emerald-500/10 border-emerald-500/20"
          badgeTexto={`${reservasAvulsas.length} ${
            reservasAvulsas.length === 1 ? "reserva" : "reservas"
          }`}
          reservas={reservasAvulsas}
          tipoSecao="avulsa"
          emptyMessage="Nenhuma reserva avulsa ou de balcão para hoje."
        />

        {/* 2. Aulas de Escolinhas */}
        <TabelaSecaoReservas
          idSecao="secao-aulas-escolinhas"
          titulo="Aulas de Escolinhas"
          subtitulo="Turmas de treinamento esportivo e escolinhas parceiras"
          icone={GraduationCap}
          badgeCor="text-violet-300 bg-violet-500/15 border-violet-500/30"
          badgeTexto={`${reservasEscolinhas.length} ${
            reservasEscolinhas.length === 1 ? "turma" : "turmas"
          }`}
          reservas={reservasEscolinhas}
          tipoSecao="escolinha"
          emptyMessage="Nenhuma aula de escolinha agendada para hoje."
        />

        {/* 3. Grupos e Mensalistas */}
        <TabelaSecaoReservas
          idSecao="secao-grupos-mensalistas"
          titulo="Grupos & Mensalistas"
          subtitulo="Peladas fixas e grupos com horários semanais cativos"
          icone={UsersRound}
          badgeCor="text-sky-300 bg-sky-500/15 border-sky-500/30"
          badgeTexto={`${reservasGrupos.length} ${
            reservasGrupos.length === 1 ? "grupo" : "grupos"
          }`}
          reservas={reservasGrupos}
          tipoSecao="grupo"
          emptyMessage="Nenhum grupo ou mensalista agendado para hoje."
        />

        {/* 4. Bloqueios de Manutenção (se houver no dia) */}
        {reservasBloqueios.length > 0 && (
          <TabelaSecaoReservas
            idSecao="secao-bloqueios-manutencao"
            titulo="Bloqueios de Manutenção"
            subtitulo="Horários interditados para conservação e reformas"
            icone={Wrench}
            badgeCor="text-amber-300 bg-amber-500/15 border-amber-500/30"
            badgeTexto={`${reservasBloqueios.length} ${
              reservasBloqueios.length === 1 ? "bloqueio" : "bloqueios"
            }`}
            reservas={reservasBloqueios}
            tipoSecao="bloqueio"
            emptyMessage="Nenhum bloqueio de manutenção ativo hoje."
          />
        )}
      </div>
    </div>
  );
}

// ── Sub-componente: Tabela de Seção Segmentada ───────────────────────────────

interface TabelaSecaoProps {
  idSecao: string;
  titulo: string;
  subtitulo: string;
  icone: React.ComponentType<{ className?: string }>;
  badgeCor: string;
  badgeTexto: string;
  reservas: Reserva[];
  tipoSecao: "avulsa" | "escolinha" | "grupo" | "bloqueio";
  emptyMessage: string;
}

function TabelaSecaoReservas({
  idSecao,
  titulo,
  subtitulo,
  icone: Icone,
  badgeCor,
  badgeTexto,
  reservas,
  tipoSecao,
  emptyMessage,
}: TabelaSecaoProps) {
  return (
    <div id={idSecao} className="space-y-3">
      {/* Header da Seção */}
      <div className="flex items-center justify-between px-1">
        <div className="flex items-center gap-2.5">
          <div className="w-7 h-7 rounded-lg bg-slate-800 border border-slate-700/80 flex items-center justify-center">
            <Icone className="w-4 h-4 text-slate-300" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white leading-tight">
              {titulo}
            </h3>
            <p className="text-[11px] text-slate-400 leading-tight">
              {subtitulo}
            </p>
          </div>
        </div>

        <span
          className={`text-[11px] font-semibold px-2.5 py-0.5 rounded-full border ${badgeCor}`}
        >
          {badgeTexto}
        </span>
      </div>

      {/* Conteúdo da Seção: Tabela ou Estado Vazio */}
      {reservas.length === 0 ? (
        <div className="bg-slate-900/60 border border-slate-800/80 rounded-xl p-4 text-center">
          <p className="text-slate-500 text-xs">{emptyMessage}</p>
        </div>
      ) : (
        <div className="bg-slate-900 border border-slate-700/50 rounded-2xl overflow-hidden shadow-lg shadow-black/20">
          {/* Header da tabela */}
          <div className="hidden sm:grid grid-cols-[1fr_auto_auto_auto] gap-4 px-5 py-2.5 border-b border-slate-700/50 text-[11px] font-semibold text-slate-400 uppercase tracking-wider bg-slate-800/40">
            <span>
              {tipoSecao === "escolinha"
                ? "Escolinha / Modalidade"
                : tipoSecao === "grupo"
                ? "Grupo / Responsável"
                : tipoSecao === "bloqueio"
                ? "Motivo do Bloqueio"
                : "Cliente"}
            </span>
            <span className="text-center">Quadra</span>
            <span className="text-center">Horário</span>
            <span className="text-right">Status</span>
          </div>

          {/* Linhas */}
          <div className="divide-y divide-slate-700/30">
            {reservas.map((r) => {
              const cfg = STATUS_CONFIG[r.status] ?? STATUS_CONFIG.pendente;
              const quadraNum = r.quadraId.replace("q", "");

              return (
                <a
                  key={r.id}
                  href={`/admin/reserva/${r.id}`}
                  className="w-full text-left px-5 py-3.5 flex flex-col sm:grid sm:grid-cols-[1fr_auto_auto_auto] gap-2.5 sm:gap-4 sm:items-center hover:bg-slate-800/60 active:bg-slate-800 transition-colors duration-150 cursor-pointer group"
                >
                  {/* Nome + Badge de Categoria + Detalhe */}
                  <div className="min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <p className="font-semibold text-white text-sm group-hover:text-emerald-300 transition-colors truncate">
                        {r.nomeCliente || "—"}
                      </p>

                      {/* Badges Especializados por Tipo de Reserva */}
                      {tipoSecao === "escolinha" ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-violet-500/15 text-violet-300 border border-violet-500/30">
                          🎓 Escolinha
                        </span>
                      ) : tipoSecao === "grupo" ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-sky-500/15 text-sky-300 border border-sky-500/30">
                          🔁 Mensalista
                        </span>
                      ) : tipoSecao === "bloqueio" ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-300 border border-amber-500/30">
                          ⚠️ Bloqueio
                        </span>
                      ) : r.tipoReserva === "admin_manual" ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-sky-500/15 text-sky-300 border border-sky-500/30">
                          🛡️ Balcão Admin
                        </span>
                      ) : (
                        (() => {
                          const telDigits = r.whatsappCliente
                            ? r.whatsappCliente.replace(/\D/g, "")
                            : "";
                          const isMembro = Boolean(
                            r.userId ||
                              (telDigits &&
                                getTelefonesCadastradosLocal().has(telDigits))
                          );
                          return isMembro ? (
                            <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">
                              ⭐ Cadastrado
                            </span>
                          ) : (
                            <span className="inline-flex items-center text-[10px] font-medium px-1.5 py-0.5 rounded-full bg-slate-800 text-slate-400 border border-slate-700">
                              Avulsa
                            </span>
                          );
                        })()
                      )}

                      {/* Selo Fidelidade em Reservas de Cliente */}
                      {r.reservaGratuitaFidelidade ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-purple-500/15 text-purple-300 border border-purple-500/30">
                          🎁 100% Fidelidade
                        </span>
                      ) : r.descontoFidelidade && r.descontoFidelidade > 0 ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-purple-500/15 text-purple-300 border border-purple-500/30">
                          🎁 -{formatarMoeda(r.descontoFidelidade)}
                        </span>
                      ) : null}
                    </div>

                    {/* Subtítulo informativo */}
                    <p className="text-slate-400 text-xs mt-0.5">
                      {tipoSecao === "escolinha" ? (
                        <>
                          <span className="text-violet-300 font-medium">
                            {r.esporte ?? "Futsal"}
                          </span>{" "}
                          · Turma Recorrente
                        </>
                      ) : tipoSecao === "grupo" ? (
                        <>
                          <span className="text-sky-300 font-medium">
                            {r.esporte ?? "Esporte"}
                          </span>{" "}
                          · Horário Semanal Cativo
                        </>
                      ) : tipoSecao === "bloqueio" ? (
                        <span className="text-amber-300/80">
                          {r.observacoes || "Interdição para conservação da quadra"}
                        </span>
                      ) : (
                        <>
                          {r.esporte ?? "Sem esporte"} ·{" "}
                          {r.reservaGratuitaFidelidade
                            ? "🎁 Grátis por Fidelidade"
                            : r.valorPendente === 0
                            ? `${formatarMoeda(r.valorSinal)} integral`
                            : `${formatarMoeda(r.valorSinal)} sinal`}
                        </>
                      )}
                    </p>
                  </div>

                  {/* Quadra */}
                  <div className="text-center flex-shrink-0">
                    <span className="text-xs font-semibold text-slate-300 bg-slate-800 border border-slate-700 px-2.5 py-1 rounded-lg">
                      Quadra {quadraNum}
                    </span>
                  </div>

                  {/* Horário */}
                  <div className="text-center flex-shrink-0">
                    <span className="text-xs font-mono text-slate-300 font-medium">
                      {r.horaInicio} – {r.horaFim}
                    </span>
                  </div>

                  {/* Status */}
                  <div className="sm:text-right flex-shrink-0">
                    <span
                      className={`text-xs font-semibold px-2.5 py-1 rounded-full border ${
                        r.reservaGratuitaFidelidade
                          ? "bg-purple-500/10 text-purple-300 border-purple-500/30"
                          : `${cfg.bg} ${cfg.cor}`
                      }`}
                    >
                      {r.reservaGratuitaFidelidade ? "🎁 Voucher" : cfg.label}
                    </span>
                  </div>
                </a>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

